"""Finite state search token contracts and full implementation."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='유한 상태 머신 · 토큰 배열 · 문자 분류',
                     sections=sections, questions=questions))


add('include/linux/textsearch_fsm.h', 'FSM 토큰 헤더 전체: 문자 조건과 반복 조건의 분리',
    '검색 패턴을 텍스트 정규표현식이 아니라 구조체 배열로 전달하는 형식입니다.',
    'type은 어떤 바이트를 허용할지, recur는 몇 번 허용할지, value는 특정 문자 값을 나타냅니다.',
    '배열의 바이트 길이를 공통 prepare에 넘깁니다. 열거형 이름이 정규표현식 엔진의 모든 탐색·되돌리기 의미를 보장하는 것은 아닙니다.',
    [('전체 선언', 'SPDX와 guard, types 포함, 문자 종류 enum과 최대값 매크로, 반복 enum과 최대값 매크로, ts_fsm_token 구조체 및 endif로 구성됩니다. 함수 정의나 문자표는 없습니다.'),
     ('문자 종류', 'SPECIFIC은 value와 같은 문자, WILDCARD는 모든 바이트, DIGIT/XDIGIT은 숫자·16진 숫자, PRINT/GRAPH는 표시 가능 문자 분류, ALPHA/ALNUM은 알파벳·영숫자입니다. ASCII/CNTRL/LOWER/UPPER/PUNCT/SPACE도 정의합니다. 종류 번호는 0부터 순서대로 부여하며 __TS_FSM_TYPE_MAX는 실제 종류가 아닌 끝 표식입니다.'),
     ('반복 종류', 'SINGLE은 한 번, PERHAPS는 0 또는 1번, ANY는 0회 이상, MULTI는 1회 이상입니다. HEAD_IGNORE는 앞부분을 건너뛰는 특별한 토큰이며 구현은 첫 위치이면서 뒤에 다른 토큰이 있을 때만 허용합니다. __TS_FSM_RECUR_MAX도 끝 표식이고 공개 최대값은 그보다 1 작습니다.'),
     ('구조체의 표현', 'type은 __u16, recur와 value는 각각 __u8입니다. 구현은 sizeof(ts_fsm_token) 단위로 입력을 나누고 나머지가 있으면 거부합니다. type 필드는 입력에서는 enum 번호지만 초기화 후 내부 복사본에서는 문자 분류 비트 마스크로 바뀝니다. 외부 표현과 내부 표현을 구분해야 합니다.'),
     ('CS 연결', '조건과 반복의 직교적 표현, 토큰 기반 중간 표현, sentinel과 최대 유효값, 바이트 단위 패턴 길이, 내부 정규화를 학습합니다. 이 구조체를 바이트 스트림으로 직렬화할 때 CPU 표현과 ABI를 무시한 공통 파일 형식이라고 가정하면 안 됩니다.')],
    [('SPECIFIC의 비교 대상 문자는 어느 필드에 있는가?', 'value에 있다', 'recur에 있다', 'type은 조건 종류이고 recur는 반복 종류입니다. 특정 바이트의 실제 값은 value에 둡니다.'),
     ('__TS_FSM_TYPE_MAX를 유효한 type으로 전달할 수 있는가?', '없다. 마지막 유효값은 그보다 1 작다', '있다. 와일드카드의 다른 이름이다', '끝 표식 다음에 TYPE_MAX를 끝 표식-1로 정의합니다. 구현은 이 최대값보다 큰 종류를 거부합니다.')])

add('lib/ts_fsm.c', 'FSM 검색 전체: 반복 전이와 엄격 모드의 실제 경계',
    '바이트 분류와 반복 토큰으로 입력을 순차 처리하는 단순 검색 구현입니다.',
    '토큰을 내부 비트 마스크로 변환하고 문자별 분류표와 AND하여 일치를 판정합니다. 반복은 다음 토큰의 조건을 보고 진행하며 일반 정규표현식의 완전한 backtracking은 제공하지 않습니다.',
    '시작 위치·입력 종료·마지막 반복 토큰의 특별 처리를 구분해야 합니다. 패턴을 기호 이름만 보고 정규표현식으로 치환하지 않습니다.',
    [('전체 파일 구성', 'GPL SPDX와 작성자·FSM 소개 뒤에 의존 헤더가 있습니다. ts_fsm 구조체, ASCII와 wildcard 비트, 종류 변환표와 256개 문자 분류표, match_token/find/init/조회 함수, ops와 등록·해제 및 모듈 정보가 이어집니다. 구조체는 ntokens와 flexible token 배열을 보관합니다.'),
     ('두 종류의 표', 'token_map은 외부 enum을 _ctype 비트들의 조합 또는 _A0x100, _W0x200으로 바꿉니다. SPECIFIC은 0입니다. token_lookup_tbl은 256개 바이트의 속성을 담고 모든 항목에 _W가 있어 NUL도 wildcard에 맞습니다. 0..127에만 _A가 있고, 128..159는 _W만 있습니다. 160은 공백·hard space, 192..222는 215를 제외하고 대문자, 223은 소문자, 224..255는 247을 제외하고 소문자로 분류됩니다. 유니코드 문자표는 아닙니다.'),
     ('문자 판정', 'match_token은 내부 type이 0이 아니면 lookup[d]&type이 하나라도 겹치는지 봅니다. type0이면 value==d로 특정 문자를 비교합니다. ALPHA처럼 여러 비트를 OR한 마스크는 모든 비트를 동시에 요구하는 조건이 아니라 허용 집합의 합집합입니다.'),
     ('블록 공급과 진행 위치', 'GET_NEXT_BLOCK은 consumed에 현재 block_idx를 더하고 index를 0으로 만든 뒤 공급자를 호출합니다. end_of_data는 현재 블록을 다 썼을 때만 다음 블록을 요청합니다. 토큰 상태를 유지하므로 여러 블록을 이어 처리합니다. 초기 호출에서 데이터가 하나도 없으면 토큰 반복 조건과 무관하게 미발견입니다.'),
     ('엄격 모드와 재시작', '첫 토큰이 HEAD_IGNORE가 아니면 strict입니다. TOKEN_MISMATCH는 strict일 때 실패하고, 비엄격이면 현재 block_idx를 한 칸 증가시킨 위치에서 첫 토큰부터 다시 시작합니다. 원래 매치 시작의 다음 바이트로 되돌아가는 완전 탐색이 아닙니다. 이전에 소비한 문자를 다시 검사하지 않으므로 겹치는 후보를 놓칠 수 있습니다.'),
     ('SINGLE과 PERHAPS', 'SINGLE은 입력이 있어야 하고 현재 문자도 맞아야 합니다. PERHAPS는 입력이 없거나 맞지 않으면 소비 없이 다음 토큰으로 갑니다. 맞으면 한 바이트를 소비합니다. 이후 실패했다고 optional이 소비한 문자를 돌려주는 경로는 없습니다. 예를 들어 a? 뒤에 a를 요구하는 두 토큰은 입력 a에서 첫 토큰이 소비한 뒤 두 번째가 실패합니다.'),
     ('MULTI와 ANY', 'MULTI는 먼저 최소 한 문자를 검사·소비한 뒤 ANY로 이어집니다. ANY에 다음 토큰이 있으면 그 다음 토큰에 맞는 문자가 나올 때까지 현재 토큰 조건에 맞는 문자를 소비합니다. 다음 토큰에 맞는 문자를 찾으면 소비하지 않고 다음 토큰에게 넘깁니다. 다음 조건의 반복 종류까지 포괄하는 정규표현식 탐색은 아닙니다.'),
     ('마지막 반복의 특별 경로', 'ANY에서 next==NULL이면 즉시 found_match로 갑니다. 마지막 MULTI도 최소 한 문자를 소비한 뒤 같은 경로로 갑니다. 그래서 마지막 ANY는 남은 입력을 끝까지 검사하거나 소비하지 않아도 성공할 수 있습니다. 이때 offset은 실제로 소비한 위치이며 남은 길이 끝으로 자동 이동하지 않습니다.'),
     ('HEAD_IGNORE와 시작 위치', 'HEAD_IGNORE는 다음 토큰에 맞는 문자가 나올 때까지 자기 조건에 맞는 바이트만 건너뜁니다. 건너뛸 수 없는 문자를 만나면 비엄격이어도 즉시 실패합니다. 다음 토큰의 후보를 찾으면 match_start를 그 위치로 갱신하여 무시한 접두사를 반환 위치에서 제외합니다. init이 HEAD_IGNORE 단독 사용을 거부하므로 next가 있어야 한다는 전제가 유지됩니다.'),
     ('끝 검사와 반환값', '토큰 루프를 모두 마치면 end_of_data일 때만 성공하고 아직 데이터가 있으면 미발견입니다. 다만 마지막 ANY/MULTI의 조기 성공은 이 끝 검사를 건너뜁니다. 성공 시 state->offset=consumed+block_idx를 쓰고 match_start를 반환하며 실패는 UINT_MAX입니다. 길이 0을 소비하는 성공은 같은 위치를 반복 반환할 수 있습니다.'),
     ('초기화 검증', '입력 길이가 토큰 구조체 크기의 배수인지, 최소 한 토큰인지, type/recur가 최대값 이하인지 검사합니다. TS_IGNORECASE는 거부합니다. HEAD_IGNORE는 첫 토큰이어야 하고 마지막 토큰일 수 없습니다. 실패는 ERR_PTR(-EINVAL), 공통 할당 실패는 해당 오류 포인터를 그대로 반환합니다.'),
     ('복사와 내부 표현', '할당 후 flags·ntokens를 저장하고 토큰 배열을 복사한 다음 각 type을 token_map으로 바꿉니다. 원래 패턴 배열은 수정하지 않습니다. fsm_get_pattern은 이 변환된 내부 배열을 반환하므로 이를 원래 enum 배열인 것처럼 그대로 prepare에 재입력하면 안 됩니다. get_pattern_len은 토큰 수가 아니라 전체 바이트 길이입니다.'),
     ('등록·복잡도·CS 연결', 'fsm_ops는 이름 fsm과 find/init/조회, THIS_MODULE과 리스트를 설정합니다. 추가 destroy 없이 묶음 할당을 공통 계층에서 해제합니다. init/exit은 등록·해제를 수행합니다. 소스 소개의 대략 선형이라는 표현은 동작 개요이며 토큰 수·재시작 횟수를 무시한 모든 입력의 엄밀한 증명이 아닙니다. 상태 전이, 조건 집합, lookahead, 소비량과 성공 범위의 차이를 학습합니다.')],
    [('대문자 무시 TS_IGNORECASE를 지정하면?', '-EINVAL로 초기화를 거부한다', '모든 특정 문자를 대문자로 바꾸어 검색한다', 'fsm_init은 flags&TS_IGNORECASE를 검사해 errout으로 갑니다. KMP/BM의 정규화 구현과 다릅니다.'),
     ('빈 입력에 ANY 토큰 하나만 주면 성공하는가?', '아니다. 초기 end_of_data 검사에서 실패한다', '그렇다. 항상 빈 문자열을 찾는다', '초기 데이터 공급 결과가 0이면 토큰 종류를 보기 전에 no_match로 이동합니다.'),
     ('마지막 ANY는 남은 입력 전체를 검사하는가?', '아니다. 다음 토큰이 없으면 즉시 성공한다', '그렇다. 모든 남은 문자가 조건에 맞아야 한다', 'ANY 분기의 첫 조건은 next==NULL이며 바로 found_match로 갑니다. 반환 offset은 그때까지 소비한 위치입니다.'),
     ('a의 PERHAPS 뒤에 a의 SINGLE을 두고 입력 a를 주면?', '첫 토큰이 소비하여 두 번째에서 실패한다', '자동으로 optional 소비를 되돌려 성공한다', 'PERHAPS가 맞으면 한 문자를 소비합니다. 이후 토큰이 실패했을 때 이전 선택으로 되돌리는 분기는 없습니다.'),
     ('get_pattern으로 돌려받은 type은 원래 enum 번호인가?', '아니다. 내부 문자 분류 마스크로 변환되어 있다', '그렇다. 입력 바이트를 수정 없이 그대로 반환한다', '원래 입력은 유지하지만 내부 복사본의 type은 token_map으로 치환합니다. 조회 함수는 그 내부 배열을 반환합니다.')])
